// The yachts you can race (public/game/classes.js has the same ids and sails them), the biggest first: what the
// yachts page (/yachts), the fleet page (/fleet) and the free race's set-up say about each. Today's race is sailed
// in a new one every day (lib/race.ts dailyYacht); a free race in any.

export type YachtId = 'jpk1050' | 'bavaria46' | 'dragon' | 'jclass' | 'j70' | 'rs21' | 'laser' | 'optimist' | 'ac75';
export const YACHT_IDS: readonly YachtId[] = ['jclass', 'ac75', 'bavaria46', 'jpk1050', 'dragon', 'j70', 'rs21', 'laser', 'optimist']; // by size, the biggest first: every list of them is in this order
export const DEFAULT_YACHT: YachtId = 'jpk1050';
export const isYacht = (v: unknown): v is YachtId => typeof v === 'string' && (YACHT_IDS as readonly string[]).includes(v);

type T2 = [en: string, ru: string, es?: string, de?: string, tr?: string, fr?: string]; // English, Russian
export type Yacht = {
  id: YachtId;
  name: T2; kind: T2; tagline: T2;
  about: T2[]; // paragraphs
  race: T2; // how she sails in the game
  specs: { k: T2; v: T2 }[]; // six; Length and Crew among them, which the yachts page's summary reads by name (components/fleet-view.tsx)
  speed: { up: number; down: number }; // knots, close-hauled and at her best downwind angle, in 12 knots of breeze (classes.js)
  // the free race: courses laid this many times longer than the JPK 1050's (classes.js courseK), and how long a race
  // takes her against it
  courseK: number; lineK: number; timeK: number;
};

// Seconds a mile to windward, as a measurement certificate gives them: 3600 / (V · cos TWA), her close-hauled speed (kn)
// and angle in each wind of BEAT_TWS (public/game/classes.js beatV and beat; test/contact-verdict.test.mjs holds them equal)
export const BEAT_TWS = [6, 8, 10, 12, 16, 20] as const;
export const BEAT_SECS: Record<YachtId, readonly number[]> = {
  jclass: [987, 835, 735, 664, 567, 533], ac75: [236, 179, 154, 138, 124, 120], bavaria46: [1271, 1001, 857, 768, 674, 656],
  jpk1050: [943, 787, 720, 692, 672, 669], dragon: [1122, 933, 836, 788, 760, 759], j70: [1119, 917, 824, 778, 752, 745],
  rs21: [1154, 942, 853, 803, 776, 769], laser: [1349, 1105, 994, 964, 947, 944], optimist: [1919, 1591, 1476, 1434, 1530, 1655],
};

